UPDATE loyalty_accounts
SET current_stamps = current_stamps - #{required}, rewards_earned = rewards_earned + 1, reward_rule_id = NULL
WHERE customer_id = #{customerId}

UPDATE customers
SET last_visit_at = GREATEST(COALESCE(last_visit_at, #{at}), #{at}), last_branch_id = #{branchId}
WHERE id = #{customerId}
